def transform(grid):
    g = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 7]
    if len(points) < 2:
        return g
    # Find the diagonal step shared by the 7 markers and extend that line.
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            if abs(r2-r1) == 1 and abs(c2-c1) == 1:
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                # Walk both ways from this adjacent pair, only painting background.
                for r, c in ((r1-dr, c1-dc), (r2+dr, c2+dc)):
                    while 0 <= r < len(g) and 0 <= c < len(g[0]):
                        if g[r][c] != grid[0][0]:
                            break
                        g[r][c] = 7
                        r += ( -dr if r == r1-dr else dr )
                        c += ( -dc if c == c1-dc else dc )
                return g
    return g
