def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v != bg}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        best = []
        # A diagonal adjacent pair defines the line. Extend its more open ray;
        # the opposite ray is often blocked by the small marker pattern.
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i+1:]:
                if abs(r2-r1) != 1 or abs(c2-c1) != 1:
                    continue
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                for r, c, sr, sc in ((r1-dr, c1-dc, -dr, -dc),
                                     (r2+dr, c2+dc, dr, dc)):
                    ray = []
                    while 0 <= r < h and 0 <= c < w and grid[r][c] == bg:
                        ray.append((r, c))
                        r += sr
                        c += sc
                    if len(ray) > len(best):
                        best = ray
        for r, c in best:
            out[r][c] = color
    return out
